// Pipeline Diagrams for Obsidian. Generated by scripts/templates.mjs. Do not edit.
const { Plugin } = require("obsidian");
// Generated by scripts/templates.mjs from scripts/shapes.mjs, pipeline-dsl.mjs,
// pipeline-mermaid.mjs and pipeline-browser.mjs. Do not edit.
(function () {
// Shared shape definitions for Pipeline Diagrams. Used by diagrams.mjs (the
// site images) and templates.mjs (icon pack and tool libraries), so every
// output comes from one source.

// Each diagram is written twice, <name>.svg and <name>-dark.svg, with fixed
// colors. Pages pick one with <picture> and a prefers-color-scheme media query;
// a media query inside the SVG itself is not reliable in Safari.
const THEMES = {
  "": { ink: "#1f2328", label: "#424a53", bg: "#ffffff", fill: "#d0d7de", ok: "#1a7f37", no: "#cf222e" },
  "-dark": { ink: "#e6edf3", label: "#b7bdc8", bg: "#0f1216", fill: "#3d444d", ok: "#3fb950", no: "#f85149" },
};

const style = (c) => `<style>
.s{fill:none;stroke:${c.ink};stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.d{stroke-dasharray:7 5}
.h{fill:${c.ink}}
.bg{fill:${c.bg}}
.x{fill:${c.fill};stroke:${c.ink};stroke-width:1.6}
text{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Inter,Helvetica,Arial,sans-serif;fill:${c.ink}}
.l{font-size:12.5px;fill:${c.label};text-anchor:middle}
.k{font-size:15px;font-weight:600;text-anchor:middle;dominant-baseline:central}
.t{font-size:12.5px}
.ok{fill:${c.ok};font-size:12px;font-weight:700;letter-spacing:.1em}
.no{fill:${c.no};font-size:12px;font-weight:700;letter-spacing:.1em}
</style>`;

const f = (n) => +n.toFixed(1);

function label(x, y, text, cls = "l") {
  const lines = String(text).split("\n");
  if (lines.length === 1) return `<text class="${cls}" x="${f(x)}" y="${f(y)}">${esc(text)}</text>`;
  const spans = lines.map((t, i) => `<tspan x="${f(x)}" dy="${i ? 15 : 0}">${esc(t)}</tspan>`).join("");
  return `<text class="${cls}" x="${f(x)}" y="${f(y)}">${spans}</text>`;
}

const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;");

// --- basic shapes -----------------------------------------------------------

function processor(cx, cy, { r = 26, code, lambda, name, fill } = {}) {
  let s = fill ? `<circle class="bg" cx="${f(cx)}" cy="${f(cy)}" r="${r}"/>` : "";
  s += `<circle class="s" cx="${f(cx)}" cy="${f(cy)}" r="${r}"/>`;
  if (lambda) {
    // a big λ: a full diagonal from top left to bottom right, plus a leg
    // from the center to the bottom left
    const d = r * 0.707;
    s += `<path class="s" d="M${f(cx - d)} ${f(cy - d)}L${f(cx + d)} ${f(cy + d)}M${f(cx)} ${f(cy)}L${f(cx - d)} ${f(cy + d)}"/>`;
    if (code) s += `<text class="k" x="${f(cx + r * 0.42)}" y="${f(cy - r * 0.3)}" style="font-size:13px">${esc(code)}</text>`;
  } else if (code) {
    const big = code === "λ" ? ' style="font-size:24px;font-weight:400"' : "";
    s += `<text class="k" x="${f(cx)}" y="${f(cy)}"${big}>${esc(code)}</text>`;
  }
  if (name) s += label(cx, cy + r + 18, name);
  return s;
}

// data store: (cx, top) anchored
function store(cx, top, { w = 52, h = 60, code, name } = {}) {
  const x = cx - w / 2;
  let s = `<rect class="s" x="${f(x)}" y="${top}" width="${w}" height="${h}"/>`;
  s += `<path class="s" d="M${f(x)} ${f(top + h * 0.2)}H${f(x + w)}"/>`;
  if (code) s += `<text class="k" x="${f(cx)}" y="${f(top + h * 0.6)}">${esc(code)}</text>`;
  if (name) s += label(cx, top + h + 18, name);
  return s;
}

// trigger: (cx, top) anchored, returns triangle with height h
function trigger(cx, top, { w = 64, h = 64, code, name } = {}) {
  let s = `<path class="s" d="M${f(cx)} ${top}L${f(cx + w / 2)} ${top + h}H${f(cx - w / 2)}Z"/>`;
  if (code) s += `<text class="k" x="${f(cx)}" y="${f(top + h * 0.66)}">${esc(code)}</text>`;
  if (name) s += label(cx, top + h + 18, name);
  return s;
}

function head(x, y, ang) {
  const L = 10, W = 4;
  const bx = x - L * Math.cos(ang), by = y - L * Math.sin(ang);
  const px = -Math.sin(ang) * W, py = Math.cos(ang) * W;
  return `<path class="h" d="M${f(x)} ${f(y)}L${f(bx + px)} ${f(by + py)}L${f(bx - px)} ${f(by - py)}Z"/>`;
}

const MARKS = {
  A: "M-6 6L0 -10L6 6",
  N: "M-5 6V-7L5 6V-7",
  Q: "M0 -9V5",
};

// flow line from (x1,y1) to (x2,y2)
function flow(x1, y1, x2, y2, { both, none, mark } = {}) {
  const ang = Math.atan2(y2 - y1, x2 - x1);
  const pull = 8;
  const ex = none ? x2 : x2 - pull * Math.cos(ang), ey = none ? y2 : y2 - pull * Math.sin(ang);
  const sx = both ? x1 + pull * Math.cos(ang) : x1, sy = both ? y1 + pull * Math.sin(ang) : y1;
  let s = `<path class="s" d="M${f(sx)} ${f(sy)}L${f(ex)} ${f(ey)}"/>`;
  if (!none) s += head(x2, y2, ang);
  if (both) s += head(x1, y1, ang + Math.PI);
  if (mark) {
    const mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
    s += `<path class="s" transform="translate(${f(mx)} ${f(my)}) rotate(${f((ang * 180) / Math.PI)})" d="${MARKS[mark]}"/>`;
  }
  return s;
}

// point on circle boundary towards (tx,ty), with a gap
function edge(cx, cy, r, tx, ty, gap = 4) {
  const a = Math.atan2(ty - cy, tx - cx);
  return [cx + (r + gap) * Math.cos(a), cy + (r + gap) * Math.sin(a)];
}

function bracket(x, y, w, h, lines) {
  const t = 9;
  let s = `<path class="s" d="M${x + t} ${y}H${x}V${y + h}H${x + t}"/>`;
  s += `<path class="s" d="M${x + w - t} ${y}H${x + w}V${y + h}H${x + w - t}"/>`;
  lines.forEach((ln, i) => (s += `<text class="t" x="${x + 14}" y="${y + 22 + i * 19}">${esc(ln)}</text>`));
  return s;
}

// other system: (cx, top) anchored rectangle with the system name inside
function other(cx, top, { w = 108, h = 60, code, name } = {}) {
  let s = `<rect class="s" x="${f(cx - w / 2)}" y="${top}" width="${w}" height="${h}"/>`;
  if (code) s += `<text class="k" x="${f(cx)}" y="${f(top + h / 2)}">${esc(code)}</text>`;
  if (name) s += label(cx, top + h + 18, name);
  return s;
}

// external system: (cx, top) anchored filled rectangle
function external(cx, top, { w = 60, h = 60, name } = {}) {
  let s = `<rect class="x" x="${f(cx - w / 2)}" y="${top}" width="${w}" height="${h}"/>`;
  if (name) s += label(cx, top + h + 18, name);
  return s;
}

// user facing app: (cx, top) anchored square with a cross
function app(cx, top, { w = 60, h = 60, name } = {}) {
  const x = cx - w / 2;
  let s = `<rect class="s" x="${f(x)}" y="${top}" width="${w}" height="${h}"/>`;
  s += `<path class="s" d="M${f(x)} ${top}L${f(x + w)} ${top + h}M${f(x + w)} ${top}L${f(x)} ${top + h}"/>`;
  if (name) s += label(cx, top + h + 18, name);
  return s;
}

// human: (cx, top) anchored head and shoulders, 62 high
function human(cx, top, { name } = {}) {
  let s = `<circle class="s" cx="${f(cx)}" cy="${top + 16}" r="15"/>`;
  s += `<path class="s" d="M${f(cx - 28)} ${top + 62}V${top + 50}A28 22 0 0 1 ${f(cx + 28)} ${top + 50}V${top + 62}Z"/>`;
  if (name) s += label(cx, top + 80, name);
  return s;
}


// Pipeline Diagrams as text: a small line-based language, an automatic layout
// and an SVG renderer that uses the shared shapes. No Node APIs here, so the
// same code runs in the browser (see templates.mjs, which bundles it into
// assets/js/pipeline-diagrams.js). The full specification is text-format.md.
//
//   title "Reporting pipeline"            direction LR | TB
//   trigger report timed "create report"  kind id [CODE] ["name"]
//   store items S3 "items"
//   list workers "workers": a, b, c        a list with its members
//   report -> collector                    flows: ->  <->  -A->  -N->  -Q->
//   collector <- report                    or reversed: <-  <-A-  <-N-  <-Q-
//   items, stats -> collector -A-> "nightly" generator -> reports
//   crm -> group "streaming"               flows to and from a group
//   group "streaming": kafka enrich        or a block:  group "streaming" { ... }
//   note collector "m4.xlarge\nmin: 0"     or  note collector:  + indented lines
//   note left reports "kept 90 days"       sides: left, right, above, below
//   note collector -> reports "hourly"     a note on a flow

const VERSION = "0.2.3";
const KINDS = ["processor", "lambda", "store", "trigger", "other", "external", "app", "human", "list"];
const KEYWORDS = [...KINDS, "title", "direction", "group", "note"];
const SIDES = ["left", "right", "above", "below"];
const ARROWS = {
  "->": {}, "<->": { both: true }, "-A->": { mark: "A" }, "-N->": { mark: "N" }, "-Q->": { mark: "Q" },
  // reversed: a <- b is the same flow as b -> a
  "<-": { rev: true }, "<-A-": { mark: "A", rev: true }, "<-N-": { mark: "N", rev: true }, "<-Q-": { mark: "Q", rev: true },
};
const ARROW_RE = /^(<->|<-[ANQ]-|-[ANQ]->|<-|->)/;
const ID_RE = /^[A-Za-z][A-Za-z0-9_-]*$/;

// letter codes from the processor and data store pages; others give a warning
const LANGUAGES = ["P", "R", "J", "C", "PHP", "PY", "R.", "RB", "JS", "J.", "L.", "C.", "C+", "C#"];
const CODES = {
  processor: [...LANGUAGES, "L", "Q", "λ", "LN", "LP", "LC", "K"],
  lambda: LANGUAGES,
  store: ["D", "P", "S3", "R", "RD", "RS", "M", "M.", "MC", "MS", "A", "MA", "PA", "O", "SM", "SSM"],
  trigger: ["M", "L", "E"],
};
const TRIGGER_ALIASES = { manual: "M", timed: "L", event: "E" };
const NO_CODE = new Set(["external", "app", "human", "list"]);

// --- helpers -------------------------------------------------------------------------

function distance(a, b) {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++)
    for (let j = 1; j <= b.length; j++)
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[a.length][b.length];
}

function closest(word, options) {
  let best = null, bd = Infinity;
  for (const o of options) {
    const dd = distance(word.toLowerCase(), o.toLowerCase());
    if (dd < bd) (bd = dd), (best = o);
  }
  return bd > 0 && bd <= Math.floor(word.length / 3) ? best : null;
}

// One line into tokens: strings (with \" \\ \n escapes), arrows, punctuation and
// words. "#" starts a comment at the start of a line or after a space, so codes
// like C# keep their "#". Arrows need no spaces around them: a->b works.
function tokenize(raw) {
  const tokens = [];
  let i = 0;
  while (i < raw.length) {
    const ch = raw[i];
    if (/\s/.test(ch)) { i++; continue; }
    if (ch === "#" && (i === 0 || /\s/.test(raw[i - 1]))) break;
    if (ch === '"') {
      let j = i + 1, v = "", closed = false;
      while (j < raw.length) {
        const c = raw[j];
        if (c === "\\" && j + 1 < raw.length) { v += raw[j + 1] === "n" ? "\n" : raw[j + 1]; j += 2; continue; }
        if (c === '"') { closed = true; j++; break; }
        v += c;
        j++;
      }
      if (!closed) return { error: 'a name is missing its closing quote (")' };
      tokens.push({ t: "str", v });
      i = j;
      continue;
    }
    const both = raw.slice(i).match(/^<-([ANQ])->/);
    if (both) return { error: `"<-${both[1]}->" points both ways. Use -${both[1]}-> or <-${both[1]}-, or <-> for a synchronous flow` };
    const arrow = raw.slice(i).match(ARROW_RE);
    if (arrow) {
      tokens.push({ t: "arrow", v: arrow[1] });
      i += arrow[1].length;
      continue;
    }
    if (",:{}".includes(ch)) { tokens.push({ t: ch, v: ch }); i++; continue; }
    let j = i;
    while (j < raw.length && !/[\s,:{}"]/.test(raw[j]) && !ARROW_RE.test(raw.slice(j))) j++;
    tokens.push({ t: "word", v: raw.slice(i, j) });
    i = j;
  }
  return { tokens };
}

const indentOf = (raw) => raw.match(/^\s*/)[0].replace(/\t/g, "  ").length;

// --- parser ----------------------------------------------------------------------------
// Collects every error instead of stopping at the first one. Throws an Error with
// all of them (e.errors, e.warnings); returns the model with model.warnings.

function parse(src) {
  const errors = [], warnings = [];
  const err = (line, message) => errors.push({ line, message });
  const warn = (line, message) => warnings.push({ line, message });
  const nodes = new Map(), edges = [], groups = [], notes = [], memberRefs = [];
  let title = "", direction = "LR";
  const stack = []; // open group blocks
  const lines = String(src).replace(/\r\n?/g, "\n").split("\n");

  for (let i = 0; i < lines.length; i++) {
    const n = i + 1, raw = lines[i];
    if (/^\s*%%/.test(raw)) continue; // Mermaid style comment
    const { tokens, error } = tokenize(raw);
    if (error) { err(n, error); continue; }
    if (!tokens.length) continue;
    const parent = stack.at(-1) || null;
    const t0 = tokens[0], kw = t0.t === "word" ? t0.v : "";

    if (t0.t === "}") {
      if (tokens.length > 1) err(n, 'put "}" on a line of its own');
      if (!stack.length) err(n, 'there is no open group to close with "}"');
      else stack.pop();
      continue;
    }

    if (kw === "title") {
      if (tokens[1]?.t !== "str" || tokens.length > 2) err(n, 'title needs text in quotes: title "My pipeline"');
      else title = tokens[1].v;
      continue;
    }

    if (kw === "direction") {
      const d = (tokens[1]?.v || "").toUpperCase();
      if (tokens.length !== 2 || !["LR", "TB", "TD"].includes(d)) err(n, "direction is LR (left to right) or TB (top to bottom)");
      else direction = d === "LR" ? "LR" : "TB";
      continue;
    }

    if (kw === "group" && !tokens.some((t) => t.t === "arrow")) {
      if (tokens[1]?.t !== "str") { err(n, 'group needs a name in quotes: group "name": a b, or group "name" {'); continue; }
      const g = { id: groups.length, name: tokens[1].v, parent, children: [], nodes: [], line: n };
      groups.push(g);
      if (parent) parent.children.push(g);
      let rest = tokens.slice(2);
      if (rest[0]?.t === "{") {
        if (rest.length > 1) err(n, 'put the contents of a group block on the lines after "{"');
        stack.push(g);
        continue;
      }
      if (rest[0]?.t === ":") rest = rest.slice(1);
      const members = [];
      for (const t of rest) {
        if (t.t === ",") continue;
        if (t.t !== "word") { err(n, `unexpected "${t.v}" in the list of group members`); continue; }
        members.push(t.v);
      }
      if (!members.length) err(n, `group "${g.name}" has no members. List them: group "${g.name}": a b, or open a block: group "${g.name}" {`);
      for (const id of members) memberRefs.push({ g, id, line: n });
      continue;
    }

    if (kw === "note") {
      let rest = tokens.slice(1), side = null;
      if (rest[0]?.t === "word" && SIDES.includes(rest[0].v) && rest[1]?.t === "word") side = rest.shift().v;
      let target = null;
      if (rest[0]?.t === "word" && rest[1]?.t === "arrow" && rest[2]?.t === "word") {
        const rev = ARROWS[rest[1].v].rev;
        target = { from: rest[rev ? 2 : 0].v, to: rest[rev ? 0 : 2].v, arrow: rev ? "->" : rest[1].v };
        rest = rest.slice(3);
      } else if (rest[0]?.t === "word") {
        target = { id: rest[0].v };
        rest = rest.slice(1);
      }
      if (!target) { err(n, 'note needs a shape or a flow: note collector "text", or note a -> b "text"'); continue; }
      const what = target.id || `${target.from} ${target.arrow} ${target.to}`;
      let text = null;
      if (rest[0]?.t === "str" && rest.length === 1) text = rest[0].v.split("\n");
      else if (rest[0]?.t === ":" && rest.length === 1) {
        // the note's text is on the following lines, indented further than this one
        const ind = indentOf(raw);
        text = [];
        while (i + 1 < lines.length && lines[i + 1].trim() && indentOf(lines[i + 1]) > ind) text.push(lines[++i].trim());
        if (!text.length) { err(n, `note ${what} has no text. Indent the lines below it, or use: note ${what} "text"`); continue; }
      } else {
        err(n, `note ${what} needs text: note ${what} "text", or end the line with ":" and indent the lines below it`);
        continue;
      }
      notes.push({ target, side, lines: text, line: n });
      continue;
    }

    if (KINDS.includes(kw)) {
      const kind = kw, idTok = tokens[1];
      if (!idTok || idTok.t !== "word") { err(n, `${kind} needs an id, e.g. ${kind} my_${kind} "my ${kind}"`); continue; }
      const id = idTok.v;
      if (!ID_RE.test(id)) { err(n, `"${id}" is not a valid id. An id starts with a letter and uses letters, digits, _ and -`); continue; }
      if (nodes.has(id)) { err(n, `"${id}" is declared twice (first on line ${nodes.get(id).line})`); continue; }
      let rest = tokens.slice(2), items;
      const colon = rest.findIndex((t) => t.t === ":");
      if (colon >= 0) {
        if (kind !== "list") err(n, `only a list has members after ":", e.g. list workers "workers": a, b, c`);
        else items = rest.slice(colon + 1).filter((t) => t.t !== ",").map((t) => t.v);
        rest = rest.slice(0, colon);
      }
      const words = rest.filter((t) => t.t === "word").map((t) => t.v), strs = rest.filter((t) => t.t === "str").map((t) => t.v);
      const other = rest.filter((t) => t.t !== "word" && t.t !== "str");
      if (words.length > 1 || strs.length > 1 || other.length)
        warn(n, `extra words are ignored: ${[...words.slice(1), ...strs.slice(1).map((s) => `"${s}"`), ...other.map((t) => t.v)].join(" ")}`);
      let code = words[0];
      if (kind === "trigger" && code && TRIGGER_ALIASES[code]) code = TRIGGER_ALIASES[code];
      if (code && NO_CODE.has(kind)) {
        warn(n, `${kind} doesn't use a code, so "${code}" is ignored`);
        code = undefined;
      } else if (code && CODES[kind] && !CODES[kind].includes(code)) {
        const hint = closest(code, CODES[kind]);
        warn(n, `unknown ${kind} code "${code}"${hint ? `. Did you mean ${hint}?` : `. Known codes: ${CODES[kind].join(" ")}`}`);
      }
      const name = strs[0] ?? (kind === "other" || kind === "trigger" ? "" : id);
      const nd = { id, kind, code, name, items, group: parent, notes: [], line: n };
      nodes.set(id, nd);
      if (parent) parent.nodes.push(id);
      continue;
    }

    if (!tokens.some((t) => t.t === "arrow")) {
      const hint = kw && closest(kw, KEYWORDS);
      err(n, hint ? `"${kw}" is not a statement. Did you mean ${hint}?`
        : `can't read this line. Expected a shape (${KINDS.join(", ")}), a flow (a -> b), group, note, title or direction`);
      continue;
    }
    parseFlow(tokens, n);
  }
  for (const g of stack) err(g.line, `group "${g.name}" is not closed. Add "}" on a line of its own`);

  function parseFlow(tokens, n) {
    const segments = [[]], arrows = [], names = [];
    for (let j = 0; j < tokens.length; j++) {
      const t = tokens[j];
      if (t.t === "arrow") { arrows.push(ARROWS[t.v]); names.push(""); segments.push([]); continue; }
      if (t.t === "str") {
        if (tokens[j - 1]?.t === "arrow") { names[names.length - 1] = t.v; continue; }
        if (j === tokens.length - 1 && arrows.length) {
          if (names.at(-1)) return err(n, "this flow already has a name");
          names[names.length - 1] = t.v;
          continue;
        }
        return err(n, `unexpected "${t.v}". A flow name goes right after the arrow or at the end of the line`);
      }
      if (t.t === ",") continue;
      if (t.t === "word" && t.v === "group" && tokens[j + 1]?.t === "str") { segments.at(-1).push({ group: tokens[++j].v }); continue; }
      if (t.t === "word") { segments.at(-1).push({ id: t.v }); continue; }
      return err(n, `unexpected "${t.v}" in a flow`);
    }
    if (segments.some((s) => !s.length)) return err(n, "a flow needs something on both sides of the arrow");
    arrows.forEach(({ rev, ...op }, k) => {
      for (const a of segments[k])
        for (const b of segments[k + 1]) {
          const [from, to] = rev ? [b, a] : [a, b];
          edges.push({ from: { ...from }, to: { ...to }, ...op, name: names[k], notes: [], line: n });
        }
    });
  }

  // --- resolve references ---
  const undeclared = (id) => {
    const hint = closest(id, [...nodes.keys()]);
    return `"${id}" is not declared. Add e.g.: processor ${id} "${id}"${hint ? `, or did you mean ${hint}?` : ""}`;
  };
  const within = (inner, outer) => { for (let g = inner; g; g = g.parent) if (g === outer) return true; return false; };
  for (const { g, id, line } of memberRefs) {
    const nd = nodes.get(id);
    if (!nd) { err(line, `group member ${undeclared(id)}`); continue; }
    if (nd.group === g || (nd.group && within(nd.group, g))) continue;
    if (nd.group && !within(g, nd.group)) { err(line, `"${id}" is already in group "${nd.group.name}"`); continue; }
    if (nd.group) nd.group.nodes.splice(nd.group.nodes.indexOf(id), 1);
    nd.group = g;
    g.nodes.push(id);
  }
  for (const e of edges) {
    for (const end of [e.from, e.to]) {
      if (end.id !== undefined) {
        if (!nodes.has(end.id)) err(e.line, undeclared(end.id));
        else end.node = nodes.get(end.id);
      } else {
        const found = groups.filter((g) => g.name === end.group);
        if (found.length !== 1) err(e.line, found.length ? `there are ${found.length} groups named "${end.group}"` : `there is no group "${end.group}"`);
        else end.groupRef = found[0];
      }
    }
    if (e.from.node && e.from.node === e.to.node) warn(e.line, `a flow from "${e.from.id}" to itself is not drawn`);
  }
  // a request and its response drawn as two arrows make a loop back across the diagram
  const plain = (e) => e.from.node && e.to.node && !e.both && !e.mark;
  const told = new Set();
  for (const e of edges) {
    if (!plain(e) || e.from.node === e.to.node) continue;
    const back = edges.find((x) => plain(x) && x.from.node === e.to.node && x.to.node === e.from.node);
    const key = [e.from.id, e.to.id].sort().join(" ");
    if (!back || told.has(key)) continue;
    told.add(key);
    const later = back.line > e.line ? back : e;
    warn(later.line, `flows go both ways between "${e.from.id}" and "${e.to.id}". For a request and its response, use one synchronous flow: ${e.from.id} <-> ${e.to.id}`);
  }
  for (const nt of notes) {
    const note = { side: nt.side, lines: nt.lines, line: nt.line };
    if (nt.target.id) {
      if (!nodes.has(nt.target.id)) err(nt.line, `note on ${undeclared(nt.target.id)}`);
      else nodes.get(nt.target.id).notes.push(note);
    } else {
      const { from, to, arrow } = nt.target;
      const e = edges.find((x) => x.from.id === from && x.to.id === to);
      if (!e) err(nt.line, `there is no flow ${from} ${arrow} ${to} to put this note on`);
      else e.notes.push(note);
    }
  }
  for (const g of groups) if (!g.nodes.length && !g.children.length && g.line) warn(g.line, `group "${g.name}" is empty`);

  if (errors.length) {
    errors.sort((a, b) => a.line - b.line);
    const e = new Error(errors.map((x) => `line ${x.line}: ${x.message}`).join("\n"));
    e.errors = errors;
    e.warnings = warnings;
    throw e;
  }
  warnings.sort((a, b) => a.line - b.line);
  return { title, direction, nodes: [...nodes.values()], edges, groups, warnings };
}

// Errors and warnings without throwing, e.g. for editors and agents.
function check(src) {
  try {
    return { errors: [], warnings: parse(src).warnings };
  } catch (e) {
    if (!e.errors) throw e;
    return { errors: e.errors, warnings: e.warnings };
  }
}

// --- sizes -------------------------------------------------------------------------------

const GAP_MAIN = 64, GAP_CROSS = 34, NOTE_GAP = 12, NOTE_DX = 18, GROUP_PAD = 16, GROUP_LABEL = 24;
const textWidth = (s) => Math.max(0, ...String(s).split("\n").map((l) => l.length * 7));
const noteSize = (lines) => ({ lines, w: Math.max(80, textWidth(lines.join("\n")) * 1.05 + 32), h: lines.length * 19 + 15 });

function measure(nd) {
  const [w, h] = {
    processor: [56, 56], lambda: [56, 56], store: [52, 60], trigger: [64, 60],
    other: [Math.max(108, textWidth(nd.code || "") * 1.3 + 28), 60],
    external: [60, 60], app: [60, 60], human: [56, 62], list: [94, 40],
  }[nd.kind];
  const nameLines = nd.name ? nd.name.split("\n").length : 0;
  const list = nd.items?.length ? noteSize(nd.items) : null; // a list's members, in brackets below it
  const listH = list ? 14 + list.h : 0;
  const below = listH + (nameLines ? 8 + nameLines * 15 : 0);
  const half = Math.max(w, textWidth(nd.name || ""), list ? list.w : 0) / 2;
  Object.assign(nd, { w, h, list, listH, below, nameHalf: textWidth(nd.name || "") / 2 });
  nd.ext = { l: half, r: half, t: h / 2, b: h / 2 + below };
}

// Note boxes relative to the shape centre, by side; grows the shape's extent.
function placeNotes(nd) {
  const by = { left: [], right: [], above: [], below: [] };
  for (const nt of nd.notes) by[nt.side].push(noteSize(nt.lines));
  const boxes = [];
  const total = (list) => list.reduce((s, b) => s + b.h, 0) + NOTE_GAP * Math.max(0, list.length - 1);
  const side = Math.max(nd.w / 2 + 40, nd.nameHalf + 12);
  let y = -total(by.right) / 2;
  for (const b of by.right) { boxes.push({ ...b, x: side, y, ax: side, ay: y + b.h / 2 }); y += b.h + NOTE_GAP; }
  y = -total(by.left) / 2;
  for (const b of by.left) { boxes.push({ ...b, x: -side - b.w, y, ax: -side, ay: y + b.h / 2 }); y += b.h + NOTE_GAP; }
  y = -nd.h / 2 - NOTE_GAP;
  for (const b of by.above) { y -= b.h; boxes.push({ ...b, x: NOTE_DX, y, ax: NOTE_DX, ay: y + b.h / 2 }); y -= NOTE_GAP; }
  const bx = Math.max(nd.nameHalf, nd.w / 2) + 24;
  y = nd.h / 2 + nd.below + 4;
  for (const b of by.below) { boxes.push({ ...b, x: bx, y, ax: bx, ay: y + b.h / 2, low: true }); y += b.h + NOTE_GAP; }
  for (const b of boxes) {
    nd.ext.l = Math.max(nd.ext.l, -b.x);
    nd.ext.r = Math.max(nd.ext.r, b.x + b.w);
    nd.ext.t = Math.max(nd.ext.t, -b.y);
    nd.ext.b = Math.max(nd.ext.b, b.y + b.h);
  }
  nd.noteBoxes = boxes;
}

// --- layout --------------------------------------------------------------------------------
// Layered: rank by longest path along the main axis (left to right, or top to
// bottom), long flows get waypoints in the columns they cross, columns are
// ordered by barycenter with group members kept together, and shapes are placed
// across the axis so straight chains become straight lines.

function layout(model) {
  const LR = model.direction !== "TB";
  const { nodes, edges, groups } = model;
  nodes.forEach(measure);
  const by = new Map(nodes.map((nd, i) => [nd.id, Object.assign(nd, { i })]));
  const descendants = (g) => [...g.nodes.map((id) => by.get(id)), ...g.children.flatMap(descendants)];
  const path = (nd) => { const p = []; for (let g = nd.group; g; g = g.parent) p.unshift(g); return p; };

  // flows between shapes, with flows to or from a group expanded to its members
  const lay = [];
  const inside = (g) => { const ms = new Set(descendants(g)); return { ms, inner: edges.filter((e) => ms.has(e.from.node) && ms.has(e.to.node)) }; };
  const entries = (g) => { const { ms, inner } = inside(g); const r = [...ms].filter((m) => !inner.some((e) => e.to.node === m)); return r.length ? r : [...ms]; };
  const exits = (g) => { const { ms, inner } = inside(g); const r = [...ms].filter((m) => !inner.some((e) => e.from.node === m)); return r.length ? r : [...ms]; };
  for (const e of edges) {
    const as = e.from.node ? [e.from.node] : exits(e.from.groupRef), bs = e.to.node ? [e.to.node] : entries(e.to.groupRef);
    for (const a of as) for (const b of bs) if (a !== b) lay.push({ a: a.id, b: b.id, e, group: !e.from.node || !e.to.node });
  }

  // rank: drop flows that close a cycle, then longest path
  const state = new Map(), dag = [];
  const visit = (id) => {
    state.set(id, 1);
    for (const l of lay.filter((l) => l.a === id)) {
      if (state.get(l.b) === 1) continue;
      dag.push(l);
      if (!state.get(l.b)) visit(l.b);
    }
    state.set(id, 2);
  };
  nodes.forEach((nd) => state.get(nd.id) || visit(nd.id));
  const inc = new Map(nodes.map((nd) => [nd.id, []])), out = new Map(nodes.map((nd) => [nd.id, []]));
  for (const l of dag) out.get(l.a).push(l.b), inc.get(l.b).push(l.a);
  const rank = new Map();
  const rk = (id) => {
    if (!rank.has(id)) rank.set(id, inc.get(id).length ? Math.max(...inc.get(id).map(rk)) + 1 : 0);
    return rank.get(id);
  };
  nodes.forEach((nd) => rk(nd.id));
  // sources sit right before the first shape they feed (stores next to their reader)
  for (const nd of nodes)
    if (!inc.get(nd.id).length && out.get(nd.id).length) rank.set(nd.id, Math.min(...out.get(nd.id).map((t) => rank.get(t))) - 1);
  const r0 = Math.min(0, ...rank.values());
  for (const [id, r] of rank) rank.set(id, r - r0);

  // notes: automatic side, then their size counts in the shape's extent
  for (const nd of nodes) {
    for (const nt of nd.notes) {
      if (nt.side) continue;
      const r = rank.get(nd.id);
      const busy = lay.some((l) => (l.a === nd.id && rank.get(l.b) > r) || (l.b === nd.id && rank.get(l.a) > r));
      nt.side = LR && busy ? "above" : "right";
    }
    placeNotes(nd);
  }

  // waypoints: one per column that a long flow passes
  const all = [...nodes];
  const adj = new Map(nodes.map((nd) => [nd.id, []]));
  const link = (a, b) => { adj.get(a).push(b); adj.get(b).push(a); };
  let wp = 0;
  for (const l of dag) {
    const ra = rank.get(l.a), rb = rank.get(l.b);
    if (rb - ra <= 1 || l.group) { link(l.a, l.b); continue; }
    let prev = l.a;
    l.via = [];
    for (let r = ra + 1; r < rb; r++) {
      const id = `~${wp++}`;
      const d = { id, dummy: true, ext: { l: 2, r: 2, t: 6, b: 6 }, i: all.length };
      all.push(d); by.set(id, d); rank.set(id, r); adj.set(id, []);
      link(prev, id);
      l.via.push(d);
      prev = id;
    }
    link(prev, l.b);
  }
  for (const l of lay) if (!dag.includes(l)) link(l.a, l.b); // cycles still pull shapes together

  // columns, ordered by barycenter, with the members of a group kept together
  const nr = Math.max(0, ...rank.values()) + 1;
  const cols = Array.from({ length: nr }, () => []);
  all.forEach((nd) => cols[rank.get(nd.id)].push(nd));
  const groupOf = (nd) => (nd.dummy ? [] : path(nd));
  const contiguous = (list, key, depth = 0) => {
    const units = [];
    for (const nd of list) {
      const g = groupOf(nd)[depth];
      const u = g && units.find((u) => u.g === g);
      if (u) u.list.push(nd);
      else units.push({ g, list: [nd] });
    }
    for (const u of units) u.key = u.list.reduce((s, nd) => s + key(nd), 0) / u.list.length;
    units.sort((a, b) => a.key - b.key);
    return units.flatMap((u) => (u.g ? contiguous(u.list, key, depth + 1) : u.list));
  };
  const pos = () => new Map(cols.flatMap((c) => c.map((nd, k) => [nd.id, k / Math.max(1, c.length - 1)])));
  for (let it = 0; it < 8; it++) {
    const p = pos();
    cols.forEach((c, k) => {
      const bc = (nd) => { const ns = adj.get(nd.id); return ns.length ? ns.reduce((s, id) => s + p.get(id), 0) / ns.length : p.get(nd.id); };
      c.sort((a, b) => bc(a) - bc(b) || a.i - b.i);
      cols[k] = contiguous(c, (nd) => c.indexOf(nd));
    });
  }

  // axis helpers: m is the main axis (columns), c the cross axis
  const mExt = (nd) => (LR ? [nd.ext.l, nd.ext.r] : [nd.ext.t, nd.ext.b]);
  const cExt = (nd) => (LR ? [nd.ext.t, nd.ext.b] : [nd.ext.l, nd.ext.r]);
  const gapC = LR ? GAP_CROSS : 48;

  // main axis: columns wide enough for their shapes, plus room for notes on flows
  const extraGap = Array(nr).fill(0);
  for (const l of dag) {
    if (!l.e.notes.length) continue;
    // the notes start at the middle of the flow, so the gap must hold them twice
    const sizes = l.e.notes.map((nt) => noteSize(nt.lines));
    const need = LR ? 2 * (14 + textWidth(l.e.name) / 2 + sizes.reduce((s, b) => s + b.w + NOTE_GAP, 0) + 10) - GAP_MAIN
      : 2 * (sizes.reduce((s, b) => s + b.h + NOTE_GAP, 0) + 14) - GAP_MAIN;
    const r = rank.get(l.a);
    extraGap[r] = Math.max(extraGap[r], need);
  }
  let m = 0;
  cols.forEach((c, k) => {
    const lo = Math.max(...c.map((nd) => mExt(nd)[0]), 10), hi = Math.max(...c.map((nd) => mExt(nd)[1]), 10);
    c.forEach((nd) => (nd.m = m + lo));
    m += lo + hi + GAP_MAIN + extraGap[k];
  });

  // cross axis: stack, then relax toward neighbours while keeping order and spacing
  for (const c of cols) {
    let y = 0;
    for (const nd of c) { const [a, b] = cExt(nd); nd.c = y + a; y += a + b + gapC; }
    const mid = (y - gapC) / 2;
    c.forEach((nd) => (nd.c -= mid));
  }
  const median = (v) => { v.sort((a, b) => a - b); const h = v.length >> 1; return v.length % 2 ? v[h] : (v[h - 1] + v[h]) / 2; };
  const place = (c, want) => {
    const off = [0];
    for (let k = 1; k < c.length; k++) off[k] = off[k - 1] + cExt(c[k - 1])[1] + gapC + cExt(c[k])[0];
    const blocks = [];
    c.forEach((nd, k) => {
      blocks.push({ sum: want[k] - off[k], n: 1 });
      while (blocks.length > 1 && blocks.at(-2).sum / blocks.at(-2).n > blocks.at(-1).sum / blocks.at(-1).n) {
        const b = blocks.pop(); blocks.at(-1).sum += b.sum; blocks.at(-1).n += b.n;
      }
    });
    let k = 0;
    for (const b of blocks) for (let j = 0; j < b.n; j++, k++) c[k].c = b.sum / b.n + off[k];
  };
  for (let it = 0; it < 8; it++) {
    const forward = it % 2 === 0;
    const order = cols.map((_, k) => (forward ? k : cols.length - 1 - k));
    for (const k of order) {
      const c = cols[k];
      place(c, c.map((nd) => {
        const ns = adj.get(nd.id);
        const side = ns.filter((id) => (forward ? rank.get(id) < k : rank.get(id) > k)).map((id) => by.get(id).c);
        const any = ns.map((id) => by.get(id).c);
        return side.length ? median(side) : any.length && it > 3 ? median(any) : nd.c;
      }));
    }
  }

  // keep shapes that are not in a group out of the group's box
  const depthBelow = (g) => (g.children.length ? 1 + Math.max(...g.children.map(depthBelow)) : 0);
  const band = (g) => {
    const ms = descendants(g);
    const lo = Math.min(...ms.map((nd) => nd.c - cExt(nd)[0])), hi = Math.max(...ms.map((nd) => nd.c + cExt(nd)[1]));
    const pad = GROUP_PAD * (1 + depthBelow(g));
    return { ms: new Set(ms), r0: Math.min(...ms.map((nd) => rank.get(nd.id))), r1: Math.max(...ms.map((nd) => rank.get(nd.id))),
      lo: lo - pad - (LR ? GROUP_LABEL : 0), hi: hi + pad };
  };
  for (let pass = 0; pass < 3; pass++) {
    for (const g of groups) {
      if (!descendants(g).length) continue;
      const b = band(g);
      for (let k = b.r0; k <= b.r1; k++) {
        const c = cols[k];
        const inBlock = c.map((nd) => b.ms.has(nd));
        const first = inBlock.indexOf(true);
        const mid = (b.lo + b.hi) / 2;
        let moved = false;
        const want = c.map((nd, j) => {
          if (b.ms.has(nd)) return nd.c;
          const [a, z] = cExt(nd);
          if (nd.c + z <= b.lo || nd.c - a >= b.hi) return nd.c;
          moved = true;
          const before = first >= 0 ? j < first : nd.c < mid;
          return before ? b.lo - z - gapC / 2 : b.hi + a + gapC / 2;
        });
        if (!moved) continue;
        if (first < 0) {
          const order = c.map((nd, j) => [nd, want[j]]).sort((x, y) => x[1] - y[1]);
          cols[k] = order.map((x) => x[0]);
          place(cols[k], order.map((x) => x[1]));
        } else place(c, want);
      }
    }
  }

  // widen the gap between two columns when flows between them are steep
  let shift = 0;
  cols.forEach((c, k) => {
    c.forEach((nd) => (nd.m += shift));
    const next = cols[k + 1];
    if (!next) return;
    const steep = Math.max(0, ...c.flatMap((nd) => adj.get(nd.id).filter((id) => next.includes(by.get(id))).map((id) => Math.abs(by.get(id).c - nd.c))));
    shift += Math.max(0, Math.min(steep * 0.3, 160) - 20);
  });

  for (const nd of all) {
    nd.cx = Math.round(LR ? nd.m : nd.c);
    nd.cy = Math.round(LR ? nd.c : nd.m);
  }
  model.lay = lay;
  model.dag = dag;
  model.rank = rank;
  return model;
}

// --- rendering ---------------------------------------------------------------------------

// where a ray from the shape centre towards (tx, ty) leaves the shape, plus a gap
function boundary(nd, tx, ty, gap = 5) {
  const dx = tx - nd.cx, dy = ty - nd.cy, len = Math.hypot(dx, dy) || 1, ux = dx / len, uy = dy / len;
  if (nd.kind === "processor" || nd.kind === "lambda") return [nd.cx + ux * (28 + gap), nd.cy + uy * (28 + gap)];
  const hw = nd.w / 2, hh = nd.h / 2;
  const poly = nd.kind === "trigger" ? [[0, -hh], [hw, hh], [-hw, hh]] : [[-hw, -hh], [hw, -hh], [hw, hh], [-hw, hh]];
  let best = Infinity;
  for (let k = 0; k < poly.length; k++) {
    const [ax, ay] = poly[k], [bx, by] = poly[(k + 1) % poly.length];
    const ex = bx - ax, ey = by - ay, den = ux * ey - uy * ex;
    if (Math.abs(den) < 1e-9) continue;
    const t = (ax * ey - ay * ex) / den, s = (ax * uy - ay * ux) / den;
    if (t > 0 && s >= 0 && s <= 1) best = Math.min(best, t);
  }
  if (!isFinite(best)) best = Math.max(hw, hh);
  return [nd.cx + ux * (best + gap), nd.cy + uy * (best + gap)];
}

function shape(nd) {
  const { cx, cy, w, h } = nd, top = cy - h / 2, o = { code: nd.code, name: nd.name };
  switch (nd.kind) {
    case "processor": return processor(cx, cy, { r: 26, ...o });
    case "lambda": return processor(cx, cy, { r: 26, lambda: true, ...o });
    case "store": return store(cx, top, { w, h, ...o });
    case "trigger": return trigger(cx, top, { w, h, ...o });
    case "other": return other(cx, top, { w, h, ...o });
    case "external": return external(cx, top, { w, h, name: nd.name });
    case "app": return app(cx, top, { w, h, name: nd.name });
    case "human": return human(cx, top, { name: nd.name });
    case "list": {
      let s = [cx - 27, cx - 9, cx + 9, cx + 27].map((x) => processor(x, cy, { r: 20, fill: true })).join("");
      if (nd.list) {
        const y = top + h + 14;
        s += `<path class="s" d="M${f(cx + 27)} ${f(top + h)}V${f(y)}"/>`;
        s += bracket(cx - nd.list.w / 2, y, nd.list.w, nd.list.h, nd.list.lines);
      }
      if (nd.name) s += label(cx, top + h + nd.listH + 18, nd.name);
      return s;
    }
  }
}

// A smooth flow through points, leaving and entering along the main axis. A
// u-turn (a flow back against the direction) loops under or beside the shapes.
function curve(pts, LR, { both, mark } = {}) {
  const segs = [];
  for (let k = 0; k + 1 < pts.length; k++) {
    const [ax, ay] = pts[k], [bx, by] = pts[k + 1];
    const d = Math.max(20, (LR ? bx - ax : by - ay) / 2);
    segs.push(LR ? [[ax, ay], [ax + d, ay], [bx - d, by], [bx, by]] : [[ax, ay], [ax, ay + d], [bx, by - d], [bx, by]]);
  }
  const unit = (p, q) => { const dx = q[0] - p[0], dy = q[1] - p[1], l = Math.hypot(dx, dy) || 1; return [dx / l, dy / l]; };
  const PULL = 8, first = segs[0], last = segs.at(-1);
  const tEnd = unit(last[2], last[3]), tStart = unit(first[1], first[0]);
  // the middle of the flow, for marks, names and notes (before shortening the ends)
  let mid, ang;
  if (segs.length % 2 === 0) {
    mid = pts[segs.length / 2];
    ang = LR ? 0 : Math.PI / 2;
  } else {
    const [a, c1, c2, b] = segs[(segs.length - 1) >> 1];
    mid = [(a[0] + 3 * c1[0] + 3 * c2[0] + b[0]) / 8, (a[1] + 3 * c1[1] + 3 * c2[1] + b[1]) / 8];
    ang = Math.atan2(b[1] + c2[1] - a[1] - c1[1], b[0] + c2[0] - a[0] - c1[0]);
  }
  const back = (p, t) => [p[0] - t[0] * PULL, p[1] - t[1] * PULL];
  last[3] = back(last[3], tEnd);
  last[2] = back(last[2], tEnd);
  if (both) { first[0] = back(first[0], tStart); first[1] = back(first[1], tStart); }
  let d = `M${f(first[0][0])} ${f(first[0][1])}`;
  for (const [, c1, c2, b] of segs) d += `C${f(c1[0])} ${f(c1[1])} ${f(c2[0])} ${f(c2[1])} ${f(b[0])} ${f(b[1])}`;
  let s = `<path class="s" d="${d}"/>`;
  s += head(pts.at(-1)[0], pts.at(-1)[1], Math.atan2(tEnd[1], tEnd[0]));
  if (both) s += head(pts[0][0], pts[0][1], Math.atan2(tStart[1], tStart[0]));
  if (mark) s += `<path class="s" transform="translate(${f(mid[0])} ${f(mid[1])}) rotate(${f((ang * 180) / Math.PI)})" d="${MARKS[mark]}"/>`;
  return { svg: s, mid };
}

// A flow back against the direction: straight lines with rounded corners
// through the given points. The middle of the longest leg holds marks and names.
function loop(pts, { both, mark } = {}) {
  const R = 12, PULL = 8;
  const dir = (p, q) => { const dx = q[0] - p[0], dy = q[1] - p[1], l = Math.hypot(dx, dy) || 1; return [dx / l, dy / l]; };
  const n = pts.length, tEnd = dir(pts[n - 2], pts[n - 1]), tStart = dir(pts[1], pts[0]);
  const q = pts.map((p) => [...p]);
  q[n - 1] = [q[n - 1][0] - tEnd[0] * PULL, q[n - 1][1] - tEnd[1] * PULL];
  if (both) q[0] = [q[0][0] - tStart[0] * PULL, q[0][1] - tStart[1] * PULL];
  let d = `M${f(q[0][0])} ${f(q[0][1])}`;
  for (let k = 1; k < n - 1; k++) {
    const [px, py] = q[k], a = dir(q[k], q[k - 1]), b = dir(q[k], q[k + 1]);
    const ra = Math.min(R, Math.hypot(q[k - 1][0] - px, q[k - 1][1] - py) / 2), rb = Math.min(R, Math.hypot(q[k + 1][0] - px, q[k + 1][1] - py) / 2);
    d += `L${f(px + a[0] * ra)} ${f(py + a[1] * ra)}Q${f(px)} ${f(py)} ${f(px + b[0] * rb)} ${f(py + b[1] * rb)}`;
  }
  d += `L${f(q[n - 1][0])} ${f(q[n - 1][1])}`;
  let s = `<path class="s" d="${d}"/>` + head(pts[n - 1][0], pts[n - 1][1], Math.atan2(tEnd[1], tEnd[0]));
  if (both) s += head(pts[0][0], pts[0][1], Math.atan2(tStart[1], tStart[0]));
  let best = 0, mid = pts[0];
  for (let k = 0; k + 1 < n; k++) {
    const len = Math.hypot(pts[k + 1][0] - pts[k][0], pts[k + 1][1] - pts[k][1]);
    if (len > best) { best = len; mid = [(pts[k][0] + pts[k + 1][0]) / 2, (pts[k][1] + pts[k + 1][1]) / 2]; }
  }
  if (mark) s += `<path class="s" transform="translate(${f(mid[0])} ${f(mid[1])})" d="${MARKS[mark]}"/>`;
  return { svg: s, mid };
}

function groupBoxes(model) {
  const by = new Map(model.nodes.map((nd) => [nd.id, nd]));
  const boxes = new Map();
  const box = (g) => {
    if (boxes.has(g)) return boxes.get(g);
    const parts = g.nodes.map((id) => by.get(id)).map((nd) => [nd.cx - nd.ext.l, nd.cy - nd.ext.t, nd.cx + nd.ext.r, nd.cy + nd.ext.b]);
    for (const ch of g.children) { const b = box(ch); if (b) parts.push([b.x0, b.y0 - GROUP_LABEL, b.x1, b.y1]); }
    if (!parts.length) { boxes.set(g, null); return null; }
    const b = {
      x0: Math.min(...parts.map((p) => p[0])) - GROUP_PAD, y0: Math.min(...parts.map((p) => p[1])) - GROUP_PAD,
      x1: Math.max(...parts.map((p) => p[2])) + GROUP_PAD, y1: Math.max(...parts.map((p) => p[3])) + GROUP_PAD - 4,
    };
    boxes.set(g, b);
    return b;
  };
  model.groups.forEach(box);
  return boxes;
}

function render(src, { pad = 24 } = {}) {
  const model = layout(typeof src === "string" ? parse(src) : src);
  const LR = model.direction !== "TB";
  const boxes = groupBoxes(model);
  const bounds = [];
  let body = "";

  // groups first (outer before inner), so they sit behind everything
  const depth = (g) => (g.parent ? 1 + depth(g.parent) : 0);
  for (const g of [...model.groups].sort((a, b) => depth(a) - depth(b))) {
    const b = boxes.get(g);
    if (!b) continue;
    body += `<rect class="s d" x="${f(b.x0)}" y="${f(b.y0)}" width="${f(b.x1 - b.x0)}" height="${f(b.y1 - b.y0)}" rx="2"/>`;
    body += `<text class="t" x="${f(b.x1)}" y="${f(b.y0 - 8)}" text-anchor="end" style="font-weight:600">${esc(g.name)}</text>`;
    bounds.push([b.x0, b.y0 - GROUP_LABEL, b.x1, b.y1]);
  }
  for (const nd of model.nodes) {
    body += shape(nd);
    bounds.push([nd.cx - nd.ext.l, nd.cy - nd.ext.t, nd.cx + nd.ext.r, nd.cy + nd.ext.b]);
    for (const b of nd.noteBoxes) {
      body += bracket(nd.cx + b.x, nd.cy + b.y, b.w, b.h, b.lines);
      const ax = nd.cx + b.ax, ay = nd.cy + b.ay;
      // a note below starts at the lower right of the shape, clear of the name
      const [x1, y1] = b.low ? boundary(nd, ax, nd.cy + nd.h / 2, 2) : boundary(nd, ax, ay, 2);
      body += `<path class="s" d="M${f(x1)} ${f(y1)}L${f(ax)} ${f(ay)}"/>`;
    }
  }

  // flows: out of a shape on the far side, into it on the near side; in top to
  // bottom diagrams they leave below the name, so they never cross it
  const exitPt = (nd) => (LR ? boundary(nd, nd.cx + 1e4, nd.cy)
    : nd.below ? [nd.cx, nd.cy + nd.h / 2 + nd.below + 4] : boundary(nd, nd.cx, nd.cy + 1e4));
  const entryPt = (nd) => (LR ? boundary(nd, nd.cx - 1e4, nd.cy) : boundary(nd, nd.cx, nd.cy - 1e4));
  const boxPt = (b, out) => (LR ? [out ? b.x1 + 4 : b.x0 - 4, (b.y0 + b.y1) / 2] : [(b.x0 + b.x1) / 2, out ? b.y1 + 4 : b.y0 - 4]);
  const main = (p) => (LR ? p[0] : p[1]);
  // what a backward flow must go around: shapes, group boxes, the waypoints of
  // long flows, and earlier backward flows
  const obstacles = [...model.nodes.map((x) => [x.cx - x.ext.l, x.cy - x.ext.t, x.cx + x.ext.r, x.cy + x.ext.b]),
    ...[...boxes.values()].filter(Boolean).map((bx) => [bx.x0, bx.y0 - GROUP_LABEL, bx.x1, bx.y1]),
    ...model.dag.flatMap((l) => (l.via || []).map((d) => [d.cx - 8, d.cy - 22, d.cx + 8, d.cy + 22]))];
  const legs = new Map(); // backward flows already leaving or entering a shape, to offset their legs
  const leg = (nd) => { const k = legs.get(nd) || 0; legs.set(nd, k + 1); return k * 10; };
  const around = (nd) => [...boxes.values()].filter((bx) => bx && bx.x0 <= nd.cx && nd.cx <= bx.x1 && bx.y0 <= nd.cy && nd.cy <= bx.y1);
  for (const e of model.edges) {
    const a = e.from.node, b = e.to.node;
    if (a && a === b) continue;
    const l = model.dag.find((x) => x.e === e && !x.group);
    let p0 = a ? exitPt(a) : boxPt(boxes.get(e.from.groupRef), true);
    let p3 = b ? entryPt(b) : boxPt(boxes.get(e.to.groupRef), false);
    const uturn = main(p3) <= main(p0) + 10 && a && b;
    let drawn;
    if (uturn) {
      // back against the direction: out past the edge of the source's column,
      // around everything in between, and in past the edge of the target's column
      const col = (nd) => model.nodes.filter((x) => model.rank.get(x.id) === model.rank.get(nd.id));
      const label = e.name ? 20 : 0;
      if (LR) {
        const xr = Math.max(...col(a).map((x) => x.cx + x.ext.r + 20), ...around(a).map((bx) => bx.x1 + 14)) + leg(a);
        const xl = Math.min(...col(b).map((x) => x.cx - x.ext.l - 20), ...around(b).map((bx) => bx.x0 - 14)) - leg(b);
        const Y = Math.max(...obstacles.filter((o) => o[2] >= xl && o[0] <= xr).map((o) => o[3])) + 22;
        drawn = loop([p0, [xr, p0[1]], [xr, Y], [xl, Y], [xl, p3[1]], p3], e);
        obstacles.push([xl, Y - 4, xr, Y + 4 + label]);
        bounds.push([xl, p0[1], xr, Y + 4 + label]);
      } else {
        const yb = Math.max(...col(a).map((x) => x.cy + x.ext.b + 20), ...around(a).map((bx) => bx.y1 + 14)) + leg(a);
        const yt = Math.min(...col(b).map((x) => x.cy - x.ext.t - 20), ...around(b).map((bx) => bx.y0 - GROUP_LABEL - 8)) - leg(b);
        const X = Math.max(...obstacles.filter((o) => o[3] >= yt && o[1] <= yb).map((o) => o[2])) + 22;
        drawn = loop([p0, [p0[0], yb], [X, yb], [X, yt], [p3[0], yt], p3], e);
        obstacles.push([X - 4, yt, X + 4 + (e.name ? textWidth(e.name) + 16 : 0), yb]);
        bounds.push([p0[0], yt, X + 4 + (e.name ? textWidth(e.name) + 16 : 0), yb]);
      }
    } else {
      const via = l?.via ? l.via.map((d) => [d.cx, d.cy]) : [];
      drawn = curve([p0, ...via, p3], LR, e);
      for (const [x, y] of via) bounds.push([x - 10, y - 10, x + 10, y + 10]);
    }
    const { svg, mid } = drawn;
    body += svg;
    let nameW = 0;
    if (e.name) {
      nameW = textWidth(e.name);
      body += LR ? `<text class="l" x="${f(mid[0])}" y="${f(mid[1] + (uturn ? 18 : e.mark ? -16 : -8))}">${esc(e.name)}</text>`
        : `<text class="l" x="${f(mid[0] + (e.mark ? 14 : 8))}" y="${f(mid[1] + 4)}" style="text-anchor:start">${esc(e.name)}</text>`;
      bounds.push(LR ? [mid[0] - nameW / 2, mid[1] - 30, mid[0] + nameW / 2, mid[1] + (uturn ? 24 : 0)] : [mid[0], mid[1] - 8, mid[0] + 14 + nameW, mid[1] + 8]);
    }
    // notes on a flow: above it, right of the middle (left to right), or
    // beside it, below the flow's name (top to bottom)
    let off = 0;
    for (const nt of e.notes) {
      const s = noteSize(nt.lines);
      const x = LR ? mid[0] + 14 + nameW / 2 + off : mid[0] + 24;
      const y = LR ? mid[1] - 16 - s.h : mid[1] + 12 + off;
      body += bracket(x, y, s.w, s.h, s.lines);
      body += LR ? `<path class="s" d="M${f(mid[0] + 3)} ${f(mid[1] - 3)}L${f(x)} ${f(y + s.h / 2)}"/>`
        : `<path class="s" d="M${f(mid[0] + 3)} ${f(mid[1] + 6)}L${f(x)} ${f(y + s.h / 2)}"/>`;
      bounds.push([x, y, x + s.w, y + s.h]);
      off += LR ? s.w + NOTE_GAP : s.h + NOTE_GAP;
    }
    bounds.push([Math.min(p0[0], p3[0]), Math.min(p0[1], p3[1]), Math.max(p0[0], p3[0]), Math.max(p0[1], p3[1])]);
  }

  // fit the view box around everything, with the title on top
  if (!bounds.length) bounds.push([0, 0, 0, 0]); // an empty diagram
  let minX = Math.min(...bounds.map((b) => b[0])) - pad, minY = Math.min(...bounds.map((b) => b[1])) - pad;
  const maxX = Math.max(...bounds.map((b) => b[2])) + pad, maxY = Math.max(...bounds.map((b) => b[3])) + pad;
  if (model.title) {
    body += `<text class="t" x="${f(minX + pad)}" y="${f(minY + 4)}" style="font-size:15px;font-weight:700">${esc(model.title)}</text>`;
    minY -= 24;
  }
  const W = Math.ceil(Math.max(maxX - minX, model.title ? textWidth(model.title) * 1.2 + 2 * pad : 0)), H = Math.ceil(maxY - minY);
  const aria = esc(model.title || "Pipeline diagram");
  const svg = (c) => `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="${f(minX)} ${f(minY)} ${W} ${H}" role="img" aria-label="${aria}">
<title>${aria}</title>
${style(c)}
${body}
</svg>
`;
  return { light: svg(THEMES[""]), dark: svg(THEMES["-dark"]), model, warnings: model.warnings };
}

// Converts the Pipeline Diagrams text format to Mermaid, for places that render
// Mermaid but not our format (GitHub, Notion, chat tools). Two levels:
//   basic:  standard Mermaid shapes (Mermaid 11.3 or newer), works everywhere
//   icons:  the real shapes from the "pd" icon pack, names below; needs the pack
//           registered (mermaid.registerIconPacks, or mmdc --iconPacksNamesAndUrls)
// No Node APIs here; bundled into assets/js/pipeline-diagrams.js too.

const RESERVED = new Set(["end", "graph", "flowchart", "subgraph", "style", "class", "classDef", "click", "linkStyle", "direction", "default"]);
const q = (s) => `"${String(s).replace(/"/g, "#quot;").replace(/\n/g, "<br>")}"`;

const codeSlug = (code) =>
  code.toLowerCase().replace(/#/g, "sharp").replace(/\+/g, "plus").replace(/\./g, "-dot").replace(/λ/g, "lambda");

// icon name in the pack for a shape, or null when the pack has no icon for it
function iconName(nd) {
  const base = { processor: "processor", lambda: "lambda", store: "store", trigger: "trigger", external: "external", app: "app", human: "human", list: "list" }[nd.kind];
  if (!base) return null;
  if (!nd.code) return base;
  return CODES[nd.kind]?.includes(nd.code) ? `${base}-${codeSlug(nd.code)}` : null;
}

function toMermaid(src, { icons = false } = {}) {
  const model = typeof src === "string" ? parse(src) : src;
  const ids = new Map();
  const used = new Set();
  const mid = (id) => {
    if (ids.has(id)) return ids.get(id);
    let m = id.replace(/-/g, "_");
    if (RESERVED.has(m)) m = `n_${m}`;
    while (used.has(m)) m += "_";
    used.add(m);
    ids.set(id, m);
    return m;
  };
  const out = [];
  if (model.title) out.push("---", `title: ${q(model.title)}`, "---");
  out.push(`flowchart ${model.direction === "TB" ? "TB" : "LR"}`);

  const textOf = (nd) => [nd.code, nd.name].filter(Boolean).join("\n");
  const node = (nd, ind) => {
    const id = mid(nd.id);
    if (icons) {
      const icon = iconName(nd);
      if (icon) {
        const text = [nd.name, nd.items?.join(", ")].filter(Boolean).join("\n");
        return `${ind}${id}@{ icon: "pd:${icon}", label: ${q(text || " ")}, pos: "b", h: 48 }`;
      }
    }
    switch (nd.kind) {
      case "processor": return `${ind}${id}@{ shape: circle, label: ${q(textOf(nd) || " ")} }`;
      case "lambda": return `${ind}${id}@{ shape: circle, label: ${q(["λ" + (nd.code ? " " + nd.code : ""), nd.name].filter(Boolean).join("\n"))} }`;
      case "store": return `${ind}${id}@{ shape: div-rect, label: ${q(textOf(nd) || " ")} }`;
      case "trigger": return `${ind}${id}@{ shape: tri, label: ${q(textOf(nd) || " ")} }`;
      case "other": return `${ind}${id}@{ shape: rect, label: ${q(textOf(nd) || " ")} }`;
      case "external": return `${ind}${id}@{ shape: rect, label: ${q(nd.name || " ")} }\n${ind}class ${id} external`;
      case "app": return `${ind}${id}@{ shape: win-pane, label: ${q(nd.name || " ")} }`;
      case "human": return `${ind}${id}@{ shape: stadium, label: ${q("👤 " + (nd.name || ""))} }`;
      case "list": return `${ind}${id}@{ shape: procs, label: ${q([nd.name, nd.items?.join(", ")].filter(Boolean).join("\n") || " ")} }`;
    }
  };

  // groups become subgraphs, with their shapes declared inside
  const gid = (g) => `group_${g.id + 1}`;
  const written = new Set();
  const writeGroup = (g, ind) => {
    out.push(`${ind}subgraph ${gid(g)}[${q(g.name)}]`);
    for (const id of g.nodes) { out.push(node(model.nodes.find((nd) => nd.id === id), ind + "  ")); written.add(id); }
    for (const ch of g.children) writeGroup(ch, ind + "  ");
    out.push(`${ind}end`);
  };
  for (const nd of model.nodes) if (!nd.group) { out.push(node(nd, "  ")); written.add(nd.id); }
  for (const g of model.groups) if (!g.parent) writeGroup(g, "  ");

  // flows; marks become letters on the label, notes on a flow join its label
  const end = (x) => (x.node ? mid(x.node.id) : gid(x.groupRef));
  for (const e of model.edges) {
    if (e.from.node && e.from.node === e.to.node) continue;
    const text = [[e.mark, e.name].filter(Boolean).join(": "), ...e.notes.map((nt) => nt.lines.join("\n"))].filter(Boolean).join("\n");
    const arrow = e.both ? "<-->" : "-->";
    out.push(`  ${end(e.from)} ${arrow}${text ? `|${q(text)}|` : ""} ${end(e.to)}`);
  }
  // notes on shapes: a comment shape linked with a dotted line
  let k = 0;
  for (const nd of model.nodes)
    for (const nt of nd.notes) {
      const id = `note_${++k}`;
      out.push(`  ${id}@{ shape: braces, label: ${q(nt.lines.join("\n"))} }`, `  ${mid(nd.id)} -.- ${id}`);
    }
  if (model.nodes.some((nd) => nd.kind === "external") && !(icons && model.nodes.every((nd) => nd.kind !== "external" || iconName(nd))))
    out.push("  classDef external fill:#d0d7de,stroke:#1f2328,color:#1f2328");
  return out.join("\n") + "\n";
}

// --- the "pd" icon pack, in Iconify JSON format -------------------------------------------

const S = 'fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"';
const text = (t, x, y) => {
  const size = t.length <= 2 ? 17 : t.length === 3 ? 14 : 11;
  return `<text x="${x}" y="${y}" text-anchor="middle" dominant-baseline="central" font-family="Helvetica, Arial, sans-serif" font-size="${size}" font-weight="700" fill="currentColor">${t.replace(/&/g, "&amp;").replace(/</g, "&lt;")}</text>`;
};
const BODIES = {
  processor: (c) => `<circle ${S} cx="32" cy="32" r="26"/>${c ? text(c, 32, 32) : ""}`,
  lambda: (c) => `<circle ${S} cx="32" cy="32" r="26"/><path ${S} d="M13.6 13.6L50.4 50.4M32 32L13.6 50.4"/>${c ? text(c, 43, 23).replace(/font-size="\d+"/, 'font-size="12"') : ""}`,
  store: (c) => `<rect ${S} x="10" y="5" width="44" height="54"/><path ${S} d="M10 16H54"/>${c ? text(c, 32, 38) : ""}`,
  trigger: (c) => `<path ${S} d="M32 5L60 58H4Z"/>${c ? text(c, 32, 42) : ""}`,
  external: () => `<rect x="7" y="7" width="50" height="50" fill="currentColor" fill-opacity="0.25" stroke="currentColor" stroke-width="2"/>`,
  app: () => `<rect ${S} x="7" y="7" width="50" height="50"/><path ${S} d="M7 7L57 57M57 7L7 57"/>`,
  human: () => `<circle ${S} cx="32" cy="17" r="12"/><path ${S} d="M9 59V50A23 18 0 0 1 55 50V59Z"/>`,
  list: () => [14, 26, 38, 50].map((x) => `<circle ${S} cx="${x}" cy="32" r="12"/>`).join(""),
};

function iconPack() {
  const icons = {};
  for (const [kind, body] of Object.entries(BODIES)) {
    icons[kind] = { body: body() };
    for (const code of CODES[kind] || []) icons[`${kind}-${codeSlug(code)}`] = { body: body(code) };
  }
  return { prefix: "pd", width: 64, height: 64, icons };
}

// Browser helpers for the text format, bundled into assets/js/pipeline-diagrams.js:
//   <pipeline-diagram> ... text ... </pipeline-diagram>   or   <pipeline-diagram src="file.pipeline">
//   renderAll()  turns ```pipeline code blocks on a page into diagrams
// The diagram lives in a shadow root, so its styles and the page's never mix.
// It follows the reader's light or dark mode, and Obsidian's theme-dark class.

const prefersDark = () => typeof matchMedia === "function" && matchMedia("(prefers-color-scheme: dark)").matches;
const SHADOW_CSS = ":host{display:block;overflow-x:auto}svg{display:block;max-width:100%;height:auto}"
  + ".pipeline-error{color:#cf222e;font:0.85rem/1.4 ui-monospace,monospace;white-space:pre-wrap;margin:0}"
  + "@media (prefers-color-scheme:dark){.pipeline-error{color:#f85149}}";

if (typeof customElements !== "undefined" && !customElements.get("pipeline-diagram")) {
  class PipelineDiagram extends HTMLElement {
    connectedCallback() {
      if (!this.shadowRoot) this.attachShadow({ mode: "open" });
      if (this._source === undefined) {
        const url = this.getAttribute("src");
        this._source = url ? null : this.textContent;
        if (url) fetch(url).then((r) => r.text()).then((text) => (this.source = text));
      }
      if (!this._mq && typeof matchMedia === "function") {
        this._mq = matchMedia("(prefers-color-scheme: dark)");
        this._onChange = () => this.update();
        this._mq.addEventListener?.("change", this._onChange);
      }
      this.update();
    }
    disconnectedCallback() {
      this._mq?.removeEventListener?.("change", this._onChange);
      this._mq = null;
    }
    get source() { return this._source; }
    set source(text) { this._source = text; this.update(); }
    update() {
      if (!this.shadowRoot || this._source == null) return;
      const theme = this.getAttribute("theme");
      const dark = theme === "dark" || (theme !== "light" && (document.body?.classList.contains("theme-dark") || prefersDark()));
      try {
        const out = render(this._source);
        this.result = out;
        this.shadowRoot.innerHTML = `<style>${SHADOW_CSS}</style>${dark ? out.dark : out.light}`;
        this.title = out.warnings.map((w) => `line ${w.line}: ${w.message}`).join("\n");
        this.dispatchEvent(new CustomEvent("pipeline-render", { detail: out }));
      } catch (e) {
        this.result = null;
        this.shadowRoot.innerHTML = `<style>${SHADOW_CSS}</style><pre class="pipeline-error"></pre>`;
        this.shadowRoot.querySelector("pre").textContent = e.message;
        this.dispatchEvent(new CustomEvent("pipeline-error", { detail: e }));
      }
    }
  }
  customElements.define("pipeline-diagram", PipelineDiagram);
}

// Turn code blocks into diagrams. By default the diagram goes right after the
// code block; { replace: true } puts it in the block's place.
function renderAll(selector = "pre > code.language-pipeline, div.language-pipeline, div.pipeline", { replace = false, root = document } = {}) {
  const made = [];
  for (const el of root.querySelectorAll(selector)) {
    const block = el.tagName === "CODE" ? el.closest("pre") : el;
    if (block.dataset.pipelineDone) continue;
    block.dataset.pipelineDone = "1";
    const d = document.createElement("pipeline-diagram");
    d.source = el.textContent;
    block.parentNode.insertBefore(d, block.nextSibling);
    if (replace) block.remove();
    made.push(d);
  }
  return made;
}

window.PipelineDiagrams = { VERSION, KINDS, CODES, parse, check, layout, render, toMermaid, iconPack, renderAll };
})();

module.exports = class PipelineDiagramsPlugin extends Plugin {
  onload() {
    this.registerMarkdownCodeBlockProcessor("pipeline", (source, el) => {
      const d = document.createElement("pipeline-diagram");
      d.source = source;
      el.appendChild(d);
    });
    // Obsidian switches themes with a class on <body>; redraw when it does
    this.registerEvent(this.app.workspace.on("css-change", () => {
      document.querySelectorAll("pipeline-diagram").forEach((d) => d.update());
    }));
  }
};
